/* Worker OCR de Mon TGV Max.
   Sert le modèle de langue française depuis ce fichier (aucun appel réseau pour les données),
   puis charge le moteur Tesseract. Le texte lu est ensuite analysé par des règles (parser.js), sans IA. */
var FRA_B64 = "";
(function () {
  var bin = null;
  function data() {
    if (!bin) {
      var s = atob(FRA_B64); bin = new Uint8Array(s.length);
      for (var i = 0; i < s.length; i++) bin[i] = s.charCodeAt(i);
      FRA_B64 = null;
    }
    return bin.slice(0);
  }
  var realFetch = self.fetch ? self.fetch.bind(self) : null;
  self.fetch = function (input, init) {
    var url = typeof input === 'string' ? input : (input && input.url) || '';
    if (/fra\.traineddata/.test(url)) {
      return Promise.resolve(new Response(data(), { status: 200, headers: { 'Content-Type': 'application/octet-stream' } }));
    }
    return realFetch(input, init);
  };
})();
importScripts('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.0/dist/worker.min.js');
